// Pure function: the proposed slot must parse, be in the future, and start
// inside business hours (08:00 to 18:00) in the lead's timezone.
function validateSlot(iso, timeZone, nowMs) {
  if (!iso) return { valid: false, reason: 'no_slot_proposed' };
  const start = new Date(iso);
  if (isNaN(start.getTime())) return { valid: false, reason: 'slot_unparseable' };
  if (start.getTime() <= nowMs) return { valid: false, reason: 'slot_in_past' };
  let hour = start.getUTCHours();
  try {
    hour = Number(new Intl.DateTimeFormat('en-US', { hour: 'numeric', hour12: false, timeZone: timeZone || 'Africa/Addis_Ababa' }).format(start));
  } catch (e) { /* keep UTC fallback */ }
  if (hour < 8 || hour >= 18) return { valid: false, reason: 'outside_business_hours' };
  const end = new Date(start.getTime() + 30 * 60000);
  return { valid: true, reason: '', startIso: start.toISOString(), endIso: end.toISOString() };
}

